+import type { CanvasInstance } from '@/types'
+
+export function createShareLink(canvas: CanvasInstance): string {
+  const data = JSON.stringify({
+    ...canvas,
+    notes: canvas.notes.map(n => ({ ...n })),
+  })
+  const encoded = btoa(data)
+  return `${window.location.origin}${window.location.pathname}#data=${encodeURIComponent(encoded)}`
+}
+
+export function parseShareLink(hash: string): CanvasInstance | null {
+  try {
+    const match = hash.match(/#data=([^&]+)/)
+    if (!match) return null
+    const encoded = decodeURIComponent(match[1])
+    const json = atob(encoded)
+    const data = JSON.parse(json) as CanvasInstance
+    return data
+  } catch (e) {
+    console.error('[share-link] Failed to parse:', e)
+    return null
+  }
+}
+
+export function isReadOnlyMode(): boolean {
+  return window.location.hash.includes('#data=')
+}
+
+export function getReadOnlyCanvas(): CanvasInstance | null {
+  if (!isReadOnlyMode()) return null
+  return parseShareLink(window.location.hash)
+}
