diffs.patch:
Index: canvas-lite/src/components/canvas/CanvasGrid.vue
===================================================================
--- canvas-lite/src/components/canvas/CanvasGrid.vue	
+++ canvas-lite/src/components/canvas/CanvasGrid.vue	
@@ -1,299 +1,303 @@
 <script setup lang="ts">
 import { ref, computed, onMounted, onUnmounted, watch, nextTick } from 'vue'
 import draggable from 'vuedraggable'
 import type { CanvasInstance, CanvasTemplate, CanvasBlock as CanvasBlockType, StickyNote } from '@/types'
 import CanvasBlockComp from './CanvasBlock.vue'
 import { useCanvasStore } from '@/stores'

 interface Props {
   canvas: CanvasInstance
   template: CanvasTemplate
   presentationMode: boolean
   viewport: { x: number; y: number; scale: number }
 }

 interface Emits {
   (e: 'viewport-change', viewport: { x: number; y: number; scale: number }): void
 }

 const props = defineProps<Props>()
 const emit = defineEmits<Emits>()

 const canvasStore = useCanvasStore()

 const gridRef = ref<HTMLDivElement>()
 const containerRef = ref<HTMLDivElement>()
 const isPanning = ref(false)
 const panStart = ref({ x: 0, y: 0 })
 const viewportStart = ref({ x: 0, y: 0 })

 const blocks = computed(() => props.template.blocks.sort((a, b) => a.order - b.order))

 const notesByBlock = computed(() => {
   const map = new Map<string, StickyNote[]>()
   props.canvas.notes.forEach((note: StickyNote) => {
     if (!map.has(note.blockId)) map.set(note.blockId, [])
     map.get(note.blockId)!.push(note)
   })
   map.forEach(notes => notes.sort((a: StickyNote, b: StickyNote) => a.order - b.order))
   return map
 })

 function handleWheel(event: WheelEvent) {
   if (event.ctrlKey || event.metaKey) {
     event.preventDefault()
     const container = containerRef.value
     if (!container) return

     const rect = container.getBoundingClientRect()
     const mouseX = event.clientX - rect.left
     const mouseY = event.clientY - rect.top

     const zoomFactor = event.deltaY > 0 ? 0.9 : 1.1
     const newScale = Math.min(Math.max(props.viewport.scale * zoomFactor, 0.25), 3)

     const scaleRatio = newScale / props.viewport.scale
     const newX = mouseX - (mouseX - props.viewport.x) * scaleRatio
     const newY = mouseY - (mouseY - props.viewport.y) * scaleRatio

     emit('viewport-change', { x: newX, y: newY, scale: newScale })
   }
 }

 function handlePointerDown(event: PointerEvent) {
   if (event.button !== 0) return
   if ((event.target as HTMLElement).closest('.sticky-note, .block-header, button, input, textarea, [contenteditable], .draggable-handle')) return

   isPanning.value = true
   panStart.value = { x: event.clientX, y: event.clientY }
   viewportStart.value = { x: props.viewport.x, y: props.viewport.y }
   containerRef.value?.setPointerCapture(event.pointerId)
   ;(event.target as HTMLElement).style.cursor = 'grabbing'
 }

 function handlePointerMove(event: PointerEvent) {
   if (!isPanning.value) return
   const dx = event.clientX - panStart.value.x
   const dy = event.clientY - panStart.value.y
   emit('viewport-change', {
     x: viewportStart.value.x + dx,
     y: viewportStart.value.y + dy,
     scale: props.viewport.scale,
   })
 }

 function handlePointerUp(event: PointerEvent) {
   if (!isPanning.value) return
   isPanning.value = false
   containerRef.value?.releasePointerCapture(event.pointerId)
   ;(event.target as HTMLElement).style.cursor = ''
 }

 function handleDoubleClick() {
   emit('viewport-change', { x: 0, y: 0, scale: 1 })
 }

 function handleTouchStart(event: TouchEvent) {
   if (event.touches.length === 2) {
     isPanning.value = true
     panStart.value = { x: event.touches[0].clientX, y: event.touches[0].clientY }
     viewportStart.value = { x: props.viewport.x, y: props.viewport.y }
   }
 }

 function handleTouchMove(event: TouchEvent) {
   if (!isPanning.value || event.touches.length !== 2) return
   event.preventDefault()
   const dx = event.touches[0].clientX - panStart.value.x
   const dy = event.touches[0].clientY - panStart.value.y
   emit('viewport-change', {
     x: viewportStart.value.x + dx,
     y: viewportStart.value.y + dy,
     scale: props.viewport.scale,
   })
 }

 function handleTouchEnd() {
   isPanning.value = false
 }

 function moveNoteBetweenBlocks(noteId: string, targetBlockId: string) {
   const note = props.canvas.notes.find(n => n.id === noteId)
   if (!note || note.blockId === targetBlockId) return

   const blockNotes = props.canvas.notes.filter(n => n.blockId === targetBlockId).sort((a: StickyNote, b: StickyNote) => a.order - b.order)
   const newOrder = blockNotes.length
   canvasStore.moveNote(noteId, targetBlockId, newOrder)
 }

 function reorderNotesInBlock(blockId: string, oldIndex: number, newIndex: number) {
   const blockNotes = props.canvas.notes.filter(n => n.blockId === blockId).sort((a: StickyNote, b: StickyNote) => a.order - b.order)
   if (oldIndex < 0 || oldIndex >= blockNotes.length || newIndex < 0 || newIndex >= blockNotes.length) return

   const [movedNote] = blockNotes.splice(oldIndex, 1)
   blockNotes.splice(newIndex, 0, movedNote)

   blockNotes.forEach((note: StickyNote, index: number) => {
     if (note.order !== index) {
       canvasStore.updateNote(note.id, { order: index, updatedAt: Date.now() })
     }
   })
   const currentCanvas = (canvasStore.currentCanvas as unknown as { value: CanvasInstance | null }).value
   if (currentCanvas) {
     currentCanvas.updatedAt = Date.now()
   }
 }

 onMounted(() => {
   const container = containerRef.value
   container?.addEventListener('wheel', handleWheel, { passive: false })
   container?.addEventListener('pointerdown', handlePointerDown)
   container?.addEventListener('pointermove', handlePointerMove)
   container?.addEventListener('pointerup', handlePointerUp)
   container?.addEventListener('pointerleave', handlePointerUp)
   container?.addEventListener('dblclick', handleDoubleClick)
   container?.addEventListener('touchstart', handleTouchStart, { passive: false })
   container?.addEventListener('touchmove', handleTouchMove, { passive: false })
   container?.addEventListener('touchend', handleTouchEnd)
 })

 onUnmounted(() => {
   const container = containerRef.value
   container?.removeEventListener('wheel', handleWheel)
   container?.removeEventListener('pointerdown', handlePointerDown)
   container?.removeEventListener('pointermove', handlePointerMove)
   container?.removeEventListener('pointerup', handlePointerUp)
   container?.removeEventListener('pointerleave', handlePointerUp)
   container?.removeEventListener('dblclick', handleDoubleClick)
   container?.removeEventListener('touchstart', handleTouchStart)
   container?.removeEventListener('touchmove', handleTouchMove)
   container?.removeEventListener('touchend', handleTouchEnd)
 })

 watch(() => props.viewport.scale, (newScale) => {
   if (gridRef.value) {
     gridRef.value.style.transform = `translate(${props.viewport.x}px, ${props.viewport.y}px) scale(${newScale})`
   }
 })

 const draggableOptions = {
-  group: 'canvas-notes',
+  group: {
+    name: 'canvas-notes',
+    pull: 'clone',
