 <script setup lang="ts">
 import { ref, nextTick } from 'vue'
 import { ChevronDown, Plus, Edit, Copy, Trash2 } from 'lucide-vue-next'
 import type { CanvasInstance } from '@/types'
 import { useCanvasStore } from '@/stores'

 interface Props {
   canvases: CanvasInstance[]
   currentId: string | null
 }

 interface Emits {
   (e: 'switch', id: string): void
   (e: 'new'): void
   (e: 'duplicate'): void
   (e: 'rename', id: string, name: string): void
   (e: 'delete', id: string): void
 }

 const props = defineProps<Props>()
 const emit = defineEmits<Emits>()

 const canvasStore = useCanvasStore()

 const showDropdown = ref(false)
 const editingId = ref<string | null>(null)
 const editName = ref('')

 function startRename(canvas: CanvasInstance) {
   editingId.value = canvas.id
   editName.value = canvas.name
   showDropdown.value = false
   nextTick(() => {
     const input = document.getElementById('rename-input-' + canvas.id) as HTMLInputElement | null
     input?.focus()
     input?.select()
   })
 }

 function confirmRename(canvas: CanvasInstance) {
   if (editName.value.trim() && editName.value !== canvas.name) {
     emit('rename', canvas.id, editName.value.trim())
   }
   editingId.value = null
   editName.value = ''
 }

 function cancelRename() {
   editingId.value = null
   editName.value = ''
 }

 function handleKeydown(event: KeyboardEvent, canvas: CanvasInstance) {
   if (event.key === 'Enter') confirmRename(canvas)
   else if (event.key === 'Escape') cancelRename()
 }

 function handleClickOutside(event: MouseEvent) {
   const dropdown = document.querySelector('.canvas-switcher-dropdown')
   if (dropdown && !dropdown.contains(event.target as Node)) {
     showDropdown.value = false
   }
 }

 function handleDelete(canvas: CanvasInstance) {
   if (props.canvases.length > 1 && window.confirm('确定删除此画布？')) {
     emit('delete', canvas.id)
     showDropdown.value = false
   }
 }
 </script>

