-      class="absolute left-0 top-full mt-1 min-w-[220px] max-h-60 overflow-y-auto card shadow-xl animate-fade-in scrollbar-thin"
+      class="absolute left-0 top-full mt-1 min-w-[220px] max-h-60 overflow-y-auto card shadow-xl animate-fade-in custom-scrollbar"
       role="listbox"
     >
       <button
         @click="emit('new'); showDropdown = false"
         class="dropdown-item w-full justify-start gap-2"
         role="option"
       >
         <Plus class="h-4 w-4" />
         <span>新建画布</span>
       </button>

       <hr class="my-1 border-canvas-border" />

       <div v-for="canvas in props.canvases" :key="canvas.id" class="relative">
         <div v-if="editingId === canvas.id" class="flex items-center gap-1 px-2 py-1">
           <input
             :id="'rename-input-' + canvas.id"
             v-model="editName"
             @keydown="handleKeydown($event, canvas)"
             @blur="confirmRename(canvas)"
             class="flex-1 input text-sm py-1"
             aria-label="重命名画布"
           />
         </div>
         <div v-else class="flex items-center gap-2 px-2 py-1">
           <button
             @click="emit('switch', canvas.id); showDropdown = false"
             :class="['flex-1 text-left truncate', props.currentId === canvas.id ? 'font-medium text-primary-600' : 'text-text']"
             role="option"
             :aria-selected="props.currentId === canvas.id"
           >
             {{ canvas.name }}
           </button>
           <div class="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
             <button
               @click.stop="startRename(canvas)"
               class="p-1 rounded hover:bg-gray-100 dark:hover:bg-gray-700"
               aria-label="重命名"
             >
               <Edit class="h-4 w-4" />
             </button>
             <button
