const draggableOptions = {
  group: {
    name: 'canvas-notes',
    pull: 'clone',
    put: true,
  },
  animation: 150,
  delay: 200,
  delayOnTouchOnly: true,
  touchStartThreshold: 8,
  forceFallback: true,
  fallbackTolerance: 4,
  ghostClass: 'draggable-ghost',
  chosenClass: 'draggable-chosen',
  dragClass: 'draggable-drag',
  handle: '.draggable-handle',
  swapThreshold: 0.65,
  invertSwap: true,
  direction: 'vertical',
  sort: true,
  onAdd: (evt: any) => {
    // 跨块拖拽新增：从源块移除克隆项，在目标块添加真实项
    const targetBlockId = evt.to.closest('[data-block-id]')?.dataset.blockId
    const noteId = evt.item.dataset.noteId
    if (targetBlockId && noteId) {
      // 从源块移除（如果是 clone 模式，源块会有 onRemove）
      // 这里添加到目标块
      const note = props.canvas.notes.find(n => n.id === noteId)
      if (note && note.blockId !== targetBlockId) {
        canvasStore.moveNote(noteId, targetBlockId, (evt.to.children.length - 1))
      }
    }
    // 移除克隆产生的多余节点
    evt.item.remove()
  },
  onRemove: (evt: any) => {
    // 跨块移出：SortableJS clone 模式下会触发，无需处理
  },
}

