import { ref, watch, isRef } from 'vue'

export function useLocalStorage<T>(key: string, defaultValue: T) {
  const isClient = typeof window !== 'undefined'
  const stored = ref<T>(defaultValue)
  const loaded = ref(false)

  function load(): T {
    if (!isClient) return defaultValue
    try {
      const item = localStorage.getItem(key)
      if (item) {
        const parsed = JSON.parse(item)
        stored.value = parsed
        return parsed
      }
    } catch (e) {
      console.error('[useLocalStorage] Failed to load:', e)
    }
    return defaultValue
  }

  function save(value: T) {
    if (!isClient) return
    try {
      localStorage.setItem(key, JSON.stringify(value))
      stored.value = value
    } catch (e) {
      if (e instanceof DOMException && e.name === 'QuotaExceededError') {
        console.error('[useLocalStorage] Storage quota exceeded')
      } else {
        console.error('[useLocalStorage] Failed to save:', e)
      }
    }
  }

  function remove() {
    if (!isClient) return
    localStorage.removeItem(key)
    stored.value = defaultValue
  }

  watch(() => stored.value, (newValue) => {
    save(newValue)
  }, { deep: true })

  return {
    stored,
    loaded,
    load,
    save,
    remove,
  }
}

export function useSessionStorage<T>(key: string, defaultValue: T) {
  const isClient = typeof window !== 'undefined'
  const stored = ref<T>(defaultValue)

  function load(): T {
    if (!isClient) return defaultValue
    try {
      const item = sessionStorage.getItem(key)
      if (item) {
        const parsed = JSON.parse(item)
        stored.value = parsed
        return parsed
      }
    } catch (e) {
      console.error('[useSessionStorage] Failed to load:', e)
    }
    return defaultValue
  }

  function save(value: T) {
    if (!isClient) return
    try {
      sessionStorage.setItem(key, JSON.stringify(value))
      stored.value = value
    } catch (e) {
      console.error('[useSessionStorage] Failed to save:', e)
    }
  }

  return {
    stored,
    load,
    save,
  }
}

import { ref, onMounted, onUnmounted } from 'vue'
import { useCanvasStore } from '@/stores'
import { useUIStore } from '@/stores/ui'

export function useKeyboardShortcuts() {
  const canvasStore = useCanvasStore()
  const uiStore = useUIStore()

  const isMac = navigator.platform.toUpperCase().indexOf('MAC') >= 0
  const modKey = isMac ? '⌘' : 'Ctrl'

  const shortcuts = [
    { key: 'n', meta: false, ctrl: false, shift: false, alt: false, description: '新建便利贴', action: () => { /* handled in editor */ } },
    { key: 'Delete', meta: false, ctrl: false, shift: false, alt: false, description: '删除选中', action: () => { /* handled in editor */ } },
    { key: 'Backspace', meta: false, ctrl: false, shift: false, alt: false, description: '删除选中', action: () => { /* handled in editor */ } },
    { key: 's', meta: true, ctrl: true, shift: false, alt: false, description: '创建快照', action: () => canvasStore.createSnapshot() },
    { key: 's', meta: true, ctrl: true, shift: true, alt: false, description: '保存画布', action: () => { /* handled in editor */ } },
    { key: 'e', meta: true, ctrl: true, shift: false, alt: false, description: '打开导出', action: () => uiStore.openModal('export') },
    { key: 'f', meta: false, ctrl: false, shift: false, alt: false, description: '全屏演示', action: () => uiStore.togglePresentationMode() },
    { key: '?', meta: false, ctrl: false, shift: true, alt: false, description: '快捷键帮助', action: () => uiStore.openModal('shortcuts') },
    { key: '/', meta: false, ctrl: false, shift: true, alt: false, description: '快捷键帮助', action: () => uiStore.openModal('shortcuts') },
    { key: 'Escape', meta: false, ctrl: false, shift: false, alt: false, description: '关闭弹窗/退出演示', action: () => { uiStore.closeModal(); if (uiStore.presentationMode) uiStore.setPresentationMode(false) } },
    { key: '0', meta: true, ctrl: true, shift: false, alt: false, description: '重置视图 (100%)', action: () => uiStore.resetViewport() },
    { key: '=', meta: true, ctrl: true, shift: false, alt: false, description: '放大', action: () => uiStore.zoomIn() },
    { key: '-', meta: true, ctrl: true, shift: false, alt: false, description: '缩小', action: () => uiStore.zoomOut() },
  ]

  function matchesShortcut(event: KeyboardEvent, shortcut: typeof shortcuts[0]): boolean {
    if (event.key.toLowerCase() !== shortcut.key.toLowerCase()) return false
    if (shortcut.meta && !event.metaKey && !event.ctrlKey) return false
    if (shortcut.ctrl && !event.ctrlKey && !event.metaKey) return false
    if (shortcut.shift !== event.shiftKey) return false
    if (shortcut.alt !== event.altKey) return false
    return true
  }

  function isInputFocused(): boolean {
    const active = document.activeElement
    return active instanceof HTMLInputElement ||
      active instanceof HTMLTextAreaElement ||
      (active as HTMLElement)?.isContentEditable === true
  }

  function handleKeyDown(event: KeyboardEvent) {
    if (isInputFocused() && event.key !== 'Escape') return

    for (const shortcut of shortcuts) {
      if (matchesShortcut(event, shortcut)) {
        event.preventDefault()
        shortcut.action()
        break
      }
    }
  }

  onMounted(() => {
    window.addEventListener('keydown', handleKeyDown)
  })

  onUnmounted(() => {
    window.removeEventListener('keydown', handleKeyDown)
  })

  return { shortcuts, modKey }
}

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import type { CanvasInstance, CanvasTemplate, CanvasSnapshot, StickyNote, ViewportState, CanvasMode } from '@/types'
import { getTemplateById, templates } from '@/templates'
import { generateNoteId, createEmptyNote } from '@/types/note'
import { useLocalStorage } from '@/composables/useLocalStorage'

const STORAGE_KEY = 'canvas-pro:v1'
const MAX_SNAPSHOTS = 20

export const useCanvasStore = defineStore('canvas', () => {
  const { load, save } = useLocalStorage<CanvasInstance[]>(STORAGE_KEY, [])

  const canvases = ref<CanvasInstance[]>([])
  const currentCanvasId = ref<string | null>(null)
  const template = ref<CanvasTemplate>(templates[0])

  function isValidCanvasArray(arr: any[]): boolean {
    if (!Array.isArray(arr)) return false
    return arr.every(item =>
      item &&
      typeof item.id === 'string' &&
      typeof item.templateId === 'string' &&
      typeof item.name === 'string' &&
      Array.isArray(item.notes) &&
      item.viewport &&
      typeof item.viewport.x === 'number' &&
      typeof item.viewport.y === 'number' &&
      typeof item.viewport.scale === 'number'
    )
  }

  function init() {
    const stored = load()
    if (stored.length > 0 && isValidCanvasArray(stored)) {
      canvases.value = stored
      currentCanvasId.value = stored[0].id
    } else {
      if (stored.length > 0) {
        save([])
      }
      createCanvas()
    }
  }

  const currentCanvas = computed<CanvasInstance | null>(() => {
    if (!currentCanvasId.value) return null
    return canvases.value.find(c => c.id === currentCanvasId.value) ?? null
  })

  const currentTemplate = computed(() => {
    if (!currentCanvas.value) return template.value
    return getTemplateById(currentCanvas.value.templateId)
  })

  function createCanvas(name?: string, templateId?: string, mode: CanvasMode = 'grid'): CanvasInstance {
    const id = `canvas_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`
    const tpl = templateId ? getTemplateById(templateId) : template.value
    const now = Date.now()

    const blocks = tpl.blocks.map(b => ({
      ...b,
      collapsed: false,
    }))

    const canvas: CanvasInstance = {
      id,
      templateId: tpl.id,
      name: name ?? `画布 ${canvases.value.length + 1}`,
      mode,
      notes: [],
      blocks,
      viewport: { x: 0, y: 0, scale: 1 },
      createdAt: now,
      updatedAt: now,
      snapshots: [],
    }

    canvases.value.push(canvas)
    currentCanvasId.value = id
    persist()
    return canvas
  }

  function switchCanvas(id: string) {
    const canvas = canvases.value.find(c => c.id === id)
    if (canvas) {
      currentCanvasId.value = id
    }
  }

  function deleteCanvas(id: string) {
    const index = canvases.value.findIndex(c => c.id === id)
    if (index === -1) return

    canvases.value.splice(index, 1)

    if (currentCanvasId.value === id) {
      currentCanvasId.value = canvases.value[0]?.id ?? null
      if (!currentCanvasId.value) {
        createCanvas()
      }
    }
    persist()
  }

  function renameCanvas(id: string, name: string) {
    const canvas = canvases.value.find(c => c.id === id)
    if (canvas) {
      canvas.name = name
      canvas.updatedAt = Date.now()
      persist()
    }
  }

  function duplicateCanvas(id: string): CanvasInstance {
    const source = canvases.value.find(c => c.id === id)
    if (!source) throw new Error('Canvas not found')

    const newCanvas: CanvasInstance = {
      ...source,
      id: `canvas_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
      name: `${source.name} (副本)`,
      notes: source.notes.map((n: StickyNote) => ({ ...n, id: generateNoteId(), createdAt: Date.now(), updatedAt: Date.now() })),
      blocks: source.blocks.map(b => ({ ...b })),
      snapshots: [],
      createdAt: Date.now(),
      updatedAt: Date.now(),
    }

    canvases.value.push(newCanvas)
    currentCanvasId.value = newCanvas.id
    persist()
    return newCanvas
  }

  function updateCanvas(patches: Partial<CanvasInstance>) {
    if (!currentCanvas.value) return
    Object.assign(currentCanvas.value, patches, { updatedAt: Date.now() })
    persist()
  }

  function setViewport(viewport: Partial<ViewportState>) {
    if (!currentCanvas.value) return
    currentCanvas.value.viewport = { ...currentCanvas.value.viewport, ...viewport }
  }

  function addNote(blockId: string | null, x?: number, y?: number, color?: StickyNote['color']): StickyNote {
    if (!currentCanvas.value) throw new Error('No active canvas')
    const note = createEmptyNote(blockId, x, y, color)
    currentCanvas.value.notes.push(note)
    currentCanvas.value.updatedAt = Date.now()
    persist()
    return note
  }

  function updateNote(noteId: string, patches: Partial<StickyNote>) {
    if (!currentCanvas.value) return
    const note = currentCanvas.value.notes.find((n: StickyNote) => n.id === noteId)
    if (note) {
      Object.assign(note, patches, { updatedAt: Date.now() })
      currentCanvas.value.updatedAt = Date.now()
      persist()
    }
  }

  function deleteNote(noteId: string) {
    if (!currentCanvas.value) return
    const index = currentCanvas.value.notes.findIndex((n: StickyNote) => n.id === noteId)
    if (index !== -1) {
      currentCanvas.value.notes.splice(index, 1)
      currentCanvas.value.updatedAt = Date.now()
      persist()
    }
  }

  function moveNote(noteId: string, targetBlockId: string | null, newOrder: number) {
    if (!currentCanvas.value) return
    const note = currentCanvas.value.notes.find((n: StickyNote) => n.id === noteId)
    if (note) {
      note.blockId = targetBlockId
      note.order = newOrder
      note.updatedAt = Date.now()
      currentCanvas.value.updatedAt = Date.now()
      persist()
    }
  }

  function reorderNotes(blockId: string, activeId: string, overId: string) {
    if (!currentCanvas.value) return
    const blockNotes = currentCanvas.value.notes
      .filter((n: StickyNote) => n.blockId === blockId)
      .sort((a: StickyNote, b: StickyNote) => a.order - b.order)

    const activeIndex = blockNotes.findIndex((n: StickyNote) => n.id === activeId)
    const overIndex = blockNotes.findIndex((n: StickyNote) => n.id === overId)
    if (activeIndex === -1 || overIndex === -1) return

    const [removed] = blockNotes.splice(activeIndex, 1)
    blockNotes.splice(overIndex, 0, removed)

    blockNotes.forEach((note: StickyNote, index: number) => {
      note.order = index
      note.updatedAt = Date.now()
    })
    currentCanvas.value.updatedAt = Date.now()
    persist()
  }

  function duplicateNote(noteId: string) {
    if (!currentCanvas.value) return
    const source = currentCanvas.value.notes.find((n: StickyNote) => n.id === noteId)
    if (!source) return

    const newNote: StickyNote = {
      ...source,
      id: generateNoteId(),
      title: source.title,
      content: source.content,
      createdAt: Date.now(),
      updatedAt: Date.now(),
      order: source.order + 0.5,
    }
    currentCanvas.value.notes.push(newNote)
    currentCanvas.value.updatedAt = Date.now()
    persist()
    return newNote
  }

  function createSnapshot(name?: string) {
    if (!currentCanvas.value) return
    const snapshot: CanvasSnapshot = {
      id: `snapshot_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
      name: name ?? `快照 ${currentCanvas.value.snapshots.length + 1}`,
      notes: currentCanvas.value.notes.map((n: StickyNote) => ({ ...n })),
      blocks: currentCanvas.value.blocks.map(b => ({ ...b })),
      viewport: { ...currentCanvas.value.viewport },
      createdAt: Date.now(),
    }
    currentCanvas.value.snapshots.unshift(snapshot)
    if (currentCanvas.value.snapshots.length > MAX_SNAPSHOTS) {
      currentCanvas.value.snapshots.pop()
    }
    persist()
    return snapshot
  }

  function restoreSnapshot(snapshotId: string) {
    if (!currentCanvas.value) return
    const snapshot = currentCanvas.value.snapshots.find(s => s.id === snapshotId)
    if (!snapshot) return

    currentCanvas.value.notes = snapshot.notes.map((n: StickyNote) => ({ ...n, updatedAt: Date.now() }))
    currentCanvas.value.blocks = snapshot.blocks.map(b => ({ ...b }))
    currentCanvas.value.viewport = { ...snapshot.viewport }
    currentCanvas.value.updatedAt = Date.now()
    persist()
  }

  function deleteSnapshot(snapshotId: string) {
    if (!currentCanvas.value) return
    const index = currentCanvas.value.snapshots.findIndex(s => s.id === snapshotId)
    if (index !== -1) {
      currentCanvas.value.snapshots.splice(index, 1)
      persist()
    }
  }

  function exportCanvas(): string {
    if (!currentCanvas.value) return '{}'
    return JSON.stringify(currentCanvas.value, null, 2)
  }

  function importCanvas(json: string): CanvasInstance {
    const data = JSON.parse(json) as CanvasInstance
    const newCanvas: CanvasInstance = {
      ...data,
      id: `canvas_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
      name: `${data.name} (导入)`,
      notes: data.notes.map((n: StickyNote) => ({ ...n, id: generateNoteId(), createdAt: Date.now(), updatedAt: Date.now() })),
      blocks: data.blocks.map(b => ({ ...b })),
      snapshots: [],
      createdAt: Date.now(),
      updatedAt: Date.now(),
    }
    canvases.value.push(newCanvas)
    currentCanvasId.value = newCanvas.id
    persist()
    return newCanvas
  }

  function persist() {
    save(canvases.value)
  }

  function setTemplate(tpl: CanvasTemplate) {
    template.value = tpl
  }

  return {
    canvases,
    currentCanvasId,
    template,
    currentCanvas,
    currentTemplate,
    init,
    createCanvas,
    switchCanvas,
    deleteCanvas,
    renameCanvas,
    duplicateCanvas,
    updateCanvas,
    setViewport,
    addNote,
    updateNote,
    deleteNote,
    moveNote,
    reorderNotes,
    duplicateNote,
    createSnapshot,
    restoreSnapshot,
    deleteSnapshot,
    exportCanvas,
    importCanvas,
    setTemplate,
  }
})

import { defineStore } from 'pinia'
import { ref, watch } from 'vue'

export const useUIStore = defineStore('ui', () => {
  const viewport = ref({ x: 0, y: 0, scale: 1 })
  const presentationMode = ref(false)
  const showGuide = ref(false)
  const theme = ref<'light' | 'dark' | 'auto'>('auto')
  const sidebarOpen = ref(false)
  const activeModal = ref<string | null>(null)

  function setViewport(v: { x?: number; y?: number; scale?: number }) {
    viewport.value = { ...viewport.value, ...v }
  }

  function resetViewport() {
    viewport.value = { x: 0, y: 0, scale: 1 }
  }

  function zoomIn() {
    viewport.value.scale = Math.min(viewport.value.scale * 1.2, 5)
  }

  function zoomOut() {
    viewport.value.scale = Math.max(viewport.value.scale / 1.2, 0.1)
  }

  function togglePresentationMode() {
    presentationMode.value = !presentationMode.value
  }

  function setPresentationMode(value: boolean) {
    presentationMode.value = value
  }

  function toggleGuide() {
    showGuide.value = !showGuide.value
  }

  function setTheme(t: 'light' | 'dark' | 'auto') {
    theme.value = t
    applyTheme()
  }

  function cycleTheme() {
    const order: ('light' | 'dark' | 'auto')[] = ['light', 'dark', 'auto']
    const currentIndex = order.indexOf(theme.value)
    theme.value = order[(currentIndex + 1) % 3]
    applyTheme()
  }

  function applyTheme() {
    const root = document.documentElement
    if (theme.value === 'auto') {
      const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches
      root.classList.toggle('dark', prefersDark)
    } else {
      root.classList.toggle('dark', theme.value === 'dark')
    }
  }

  function openModal(name: string) {
    activeModal.value = name
  }

  function closeModal() {
    activeModal.value = null
  }

  function toggleSidebar() {
    sidebarOpen.value = !sidebarOpen.value
  }

  watch(() => theme.value, applyTheme, { immediate: true })

  return {
    viewport,
    presentationMode,
    showGuide,
    theme,
    sidebarOpen,
    activeModal,
    setViewport,
    resetViewport,
    zoomIn,
    zoomOut,
    togglePresentationMode,
    setPresentationMode,
    toggleGuide,
    setTheme,
    cycleTheme,
    openModal,
    closeModal,
    toggleSidebar,
  }
})

import { defineStore } from 'pinia'
import { ref } from 'vue'

export const useSettingsStore = defineStore('settings', () => {
  const language = ref<'zh' | 'en'>('zh')
  const autoSaveInterval = ref(500)
  const defaultExportFormat = ref<'png' | 'pdf' | 'markdown' | 'json'>('png')
  const exportPixelRatio = ref<1 | 2 | 3>(2)
  const showGridLines = ref(true)
  const snapToGrid = ref(true)
  const showAlignmentGuides = ref(true)

  function setLanguage(lang: 'zh' | 'en') {
    language.value = lang
  }

  function setAutoSaveInterval(ms: number) {
    autoSaveInterval.value = Math.max(100, Math.min(10000, ms))
  }

  return {
    language,
    autoSaveInterval,
    defaultExportFormat,
    exportPixelRatio,
    showGridLines,
    snapToGrid,
    showAlignmentGuides,
    setLanguage,
    setAutoSaveInterval,
  }
})

import { createRouter, createWebHashHistory, type RouteRecordRaw } from 'vue-router'

const routes: RouteRecordRaw[] = [
  {
    path: '/',
    name: 'Home',
    component: () => import('@/views/HomeView.vue'),
  },
  {
    path: '/guide',
    name: 'Guide',
    component: () => import('@/views/GuideView.vue'),
  },
  {
    path: '/canvas/:id',
    name: 'CanvasEditor',
    component: () => import('@/views/CanvasEditorView.vue'),
    props: true,
  },
  {
    path: '/canvas/new',
    name: 'NewCanvas',
    component: () => import('@/views/CanvasEditorView.vue'),
    props: route => ({ template: route.query.template }),
  },
  {
    path: '/examples/:id',
    name: 'ExampleView',
    component: () => import('@/views/ExampleView.vue'),
    props: true,
  },
  {
    path: '/preview/:id',
    name: 'PreviewView',
    component: () => import('@/views/PreviewView.vue'),
    props: true,
  },
]

const router = createRouter({
  history: createWebHashHistory('/canvas-pro/'),
  routes,
  scrollBehavior() {
    return { top: 0 }
  },
})

export default router

