            if (id.includes('@dnd-kit')) return 'vendor-dnd'
            if (id.includes('html-to-image') || id.includes('pdf-lib') || id.includes('file-saver')) return 'vendor-export'
            if (id.includes('lucide-vue-next')) return 'vendor-icons'
            return 'vendor'
          }
        },
      },
    },
  },
  server: {
    port: 3000,
    open: true,
  },
})

