              h('rect', { x: '8', y: '10', width: '4', height: '4', rx: '1', fill: 'white', opacity: '0.3' }),
              h('rect', { x: '8', y: '16', width: '4', height: '4', rx: '1', fill: 'white', opacity: '0.3' }),
            ]),
            h('span', { class: 'text-lg font-semibold text-text' }, 'CanvasPro 预览'),
            h('span', { class: 'px-2 py-0.5 text-xs font-medium rounded bg-primary-100 dark:bg-primary-900 opacity-30 text-primary-700 dark:text-primary-300' }, '只读模式'),
          ]),
          h('div', { class: 'flex items-center gap-2' }, [
            h('button', { onClick: () => this.toggleFullscreen(), class: 'btn-icon', 'aria-label': this.isFullscreen ? '退出全屏' : '全屏' }, [
              h(Maximize2, { class: 'h-5 w-5' })
