        ]),
      ]),
      h('main', { class: this.mainClass }, [
        h('div', { class: 'max-w-7xl mx-auto h-full p-4' }, [
          h('div', { vIf: this.canvasData, class: 'h-full bg-canvas-bg rounded-xl border border-canvas-border overflow-hidden' }, [
            h('p', { class: 'text-center text-text-muted p-8' }, '预览模式 - 画布渲染开发中'),
