      h('div', { vIf: !this.presentationMode && !this.isEditing, class: 'absolute top-1 right-1 opacity-0 group-hover:opacity-100 transition-opacity' }, [
        h('button', { vBind: this.listeners, class: 'p-1 rounded hover:bg-black/10 dark:hover:bg-white/10 touch-pan-y', 'aria-label': '拖拽移动', onPointerdown: this.handlePointerDown }, [
          h(GripVertical, { class: 'h-5 w-5 text-text-muted' }),
        ]),
      ]),
    ])
  },
}
</script>

import { h } from 'vue'
import { ChevronDown, Plus, GripVertical } from 'lucide-vue-next'

export default {
  setup() {
    const props = defineProps({
      block: { type: Object, required: true },
      noteCount: { type: Number, required: true },
      collapsed: { type: Boolean, required: true },
      presentationMode: { type: Boolean, required: true },
    })

    const emit = defineEmits(['toggle-collapse', 'add-note'])

    return { props, emit }
  },
  render() {
    return h('div', {
      class: 'flex items-center justify-between px-4 py-3 bg-gray-50 dark:bg-gray-800/50 border-b border-canvas-border',
      class: { 'cursor-pointer': !this.props.presentationMode },
      style: { backgroundColor: this.props.block.color ? this.props.block.color + '20' : 'transparent' },
    }, [
      h('div', { class: 'flex items-center gap-3 min-w-0 flex-1' }, [
        h('button', {
          vIf: !this.props.presentationMode,
          onClick: () => this.emit('toggle-collapse'),
          class: 'p-1 rounded hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors',
          'aria-label': this.props.collapsed ? '展开' : '折叠',
          'aria-expanded': !this.props.collapsed,
        }, [
          h(ChevronDown, { class: this.props.collapsed ? 'rotate-180' : '', class: 'h-5 w-5 text-text-muted' }),
        ]),
        h('h3', { class: 'font-semibold text-text truncate', style: { color: this.props.block.color } }, this.props.block.title),
        h('span', { class: 'px-2 py-0.5 text-xs font-medium bg-primary-100 dark:bg-primary-900/30 text-primary-700 dark:text-primary-300 rounded-full' }, this.props.noteCount),
      ]),
      h('button', {
        vIf: !this.props.presentationMode,
        onClick: () => this.emit('add-note'),
        class: 'btn-icon text-text-muted hover:text-primary-600 dark:hover:text-primary-400',
