      const templateId = route.params.template
      if (!canvasStore.currentCanvas || canvasStore.currentCanvasId !== route.params.id) {
        if (route.params.id === 'new') {
          canvasStore.createCanvas(undefined, templateId)
        } else {
          canvasStore.switchCanvas(route.params.id)
        }
      }
    })

    return () => h('div', { class: 'min-h-screen bg-canvas-bg' }, [
      h('p', { class: 'text-center text-text-muted p-8' }, '画布编辑器 - 开发中'),
      h('p', { class: 'text-center text-text-muted' }, 'Canvas ID: ' + route.params.id),
    ])
  },
}
</script>

