import { h, ref } from 'vue'
import { X, Keyboard, Mouse, Monitor, Command, ChevronDown, ChevronUp } from 'lucide-vue-next'

export default {
  emits: ['close'],
  setup() {
    const emit = defineEmits(['close'])

    const isMac = navigator.platform.toUpperCase().indexOf('MAC') >= 0
    const modKey = isMac ? '⌘' : 'Ctrl'
    const modKeyLabel = isMac ? 'Command' : 'Ctrl'

    const shortcuts = [
      { category: 'Canvas', items: [
        { key: `${modKey}+Shift+N`, desc: 'New Canvas' },
        { key: `${modKey}+Shift+D`, desc: 'Duplicate Canvas' },
        { key: 'F', desc: 'Toggle Presentation' },
        { key: 'Esc', desc: 'Exit Presentation / Close Modal' },
        { key: `${modKey}+0`, desc: 'Reset View (100%)' },
        { key: `${modKey}+=`, desc: 'Zoom In' },
        { key: `${modKey}+-`, desc: 'Zoom Out' },
        { key: `${modKey}+Wheel`, desc: 'Zoom Canvas' },
        { key: 'Space+Drag', desc: 'Pan Canvas' },
        { key: 'Double Click', desc: 'Reset View' },
      ]},
      { category: 'Sticky Notes', items: [
        { key: 'N', desc: 'Create Sticky Note' },
        { key: 'Enter', desc: 'Edit Selected Note' },
        { key: 'Delete / Backspace', desc: 'Delete Selected Note' },
        { key: 'Up / Down', desc: 'Move Note Position' },
        { key: `${modKey}+C`, desc: 'Copy Note' },
        { key: `${modKey}+V`, desc: 'Paste Note' },
        { key: `${modKey}+S`, desc: 'Create Snapshot' },
        { key: `${modKey}+Shift+S`, desc: 'Save Canvas' },
      ]},
      { category: 'Editing', items: [
        { key: `${modKey}+B`, desc: 'Bold' },
        { key: `${modKey}+I`, desc: 'Italic' },
        { key: `${modKey}+U`, desc: 'Underline' },
        { key: `${modKey}+Shift+7`, desc: 'Ordered List' },
        { key: `${modKey}+Shift+8`, desc: 'Unordered List' },
        { key: `${modKey}+K`, desc: 'Insert Link' },
      ]},
      { category: 'Export & Other', items: [
        { key: `${modKey}+E`, desc: 'Open Export Dialog' },
        { key: `${modKey}+Shift+E`, desc: 'Quick Export PNG' },
        { key: '? / Shift+/', desc: 'Show Shortcuts Help' },
        { key: 'Left / Right', desc: 'Switch Canvas in Presentation' },
      ]},
    ]

    function close() {
      emit('close')
    }

    function getKeyDisplay(key) {
      return key.replace('Ctrl', modKey).replace('⌘', modKey).replace('Command', modKeyLabel)
    }

    return {
      isMac,
      modKey,
      modKeyLabel,
      shortcuts,
      close,
      getKeyDisplay,
    }
  },
  render() {
    return h('div', {
      class: 'fixed inset-0 z-50 flex items-center justify-center bg-black opacity-50 backdrop-blur-sm animate-fade-in',
      onClick: this.close,
    }, [
      h('div', {
        class: 'relative w-full max-w-3xl max-h-[90vh] mx-4 card animate-scale-in overflow-hidden flex flex-col',
        onClick: (e) => e.stopPropagation(),
      }, [
        h('div', { class: 'flex items-center justify-between p-4 border-b border-canvas-border' }, [
          h('div', { class: 'flex items-center gap-2' }, [
            h(Keyboard, { class: 'h-5 w-5 text-primary-500' }),
            h('h2', { class: 'text-lg font-semibold' }, 'Shortcuts Help'),
            h('span', {
              class: 'px-2 py-0.5 text-xs font-medium rounded bg-primary-100 dark:bg-primary-900 opacity-30 text-primary-700 dark:text-primary-300',
            }, this.modKeyLabel + ' = ' + (this.isMac ? '⌘ Command' : 'Ctrl')),
          ]),
          h('button', { onClick: this.close, class: 'btn-icon text-text-muted hover:text-text', ariaLabel: 'Close' }, [
            h(X, { class: 'h-5 w-5' }),
          ]),
        ]),
        h('div', { class: 'flex-1 overflow-y-auto p-4 space-y-6' }, [
          this.shortcuts.map(group => h('div', { key: group.category, class: 'space-y-3' }, [
            h('h3', { class: 'text-sm font-medium text-text-muted uppercase tracking-wider' }, group.category),
            h('div', { class: 'grid grid-cols-1 sm:grid-cols-2 gap-2' }, group.items.map(item =>
              h('div', { key: item.key, class: 'flex items-center gap-3 p-3 rounded-lg bg-gray-50 dark:bg-gray-800 opacity-50' }, [
                h('kbd', {
                  class: 'font-mono text-xs px-2 py-1 rounded whitespace-nowrap bg-white dark:bg-gray-700 border border-canvas-border',
                }, this.getKeyDisplay(item.key)),
                h('span', { class: 'text-sm text-text' }, item.desc),
              ),
            )),
          ])),
          h('div', { class: 'pt-4 border-t border-canvas-border text-center' }, [
            h('p', { class: 'text-sm text-text-muted' }, 'Tip: Letter shortcuts are disabled in input fields'),
          ]),
        ]),
      ]),
    ])
  },
}
</script>

