    const isMac = navigator.platform.toUpperCase().indexOf('MAC') >= 0
    const modKey = isMac ? '⌘' : 'Ctrl'
    const modKeyLabel = isMac ? 'Command' : 'Ctrl'

    const shortcuts = [
      { category: 'Canvas', items: [
        { key: `${modKey}+Shift+N`, desc: 'New Canvas' },
        { key: `${modKey}+Shift+D`, desc: 'Duplicate Canvas' },
        { key: 'F', desc: 'Toggle Presentation' },
        { key: 'Esc', desc: 'Exit Presentation / Close Modal' },
        { key: `${modKey}+0`, desc: 'Reset View (100%)' },
        { key: `${modKey}+=`, desc: 'Zoom In' },
        { key: `${modKey}+-`, desc: 'Zoom Out' },
        { key: `${modKey}+Wheel`, desc: 'Zoom Canvas' },
        { key: 'Space+Drag', desc: 'Pan Canvas' },
        { key: 'Double Click', desc: 'Reset View' },
      ]},
      { category: 'Sticky Notes', items: [
        { key: 'N', desc: 'Create Sticky Note' },
        { key: 'Enter', desc: 'Edit Selected Note' },
        { key: 'Delete / Backspace', desc: 'Delete Selected Note' },
        { key: 'Up / Down', desc: 'Move Note Position' },
        { key: `${modKey}+C`, desc: 'Copy Note' },
        { key: `${modKey}+V`, desc: 'Paste Note' },
        { key: `${modKey}+S`, desc: 'Create Snapshot' },
        { key: `${modKey}+Shift+S`, desc: 'Save Canvas' },
      ]},
      { category: 'Editing', items: [
        { key: `${modKey}+B`, desc: 'Bold' },
        { key: `${modKey}+I`, desc: 'Italic' },
        { key: `${modKey}+U`, desc: 'Underline' },
        { key: `${modKey}+Shift+7`, desc: 'Ordered List' },
        { key: `${modKey}+Shift+8`, desc: 'Unordered List' },
        { key: `${modKey}+K`, desc: 'Insert Link' },
      ]},
      { category: 'Export & Other', items: [
        { key: `${modKey}+E`, desc: 'Open Export Dialog' },
        { key: `${modKey}+Shift+E`, desc: 'Quick Export PNG' },
        { key: '? / Shift+/', desc: 'Show Shortcuts Help' },
        { key: 'Left / Right', desc: 'Switch Canvas in Presentation' },
      ]},
