          h('div', { class: 'flex items-center gap-2' }, [
            h(Keyboard, { class: 'h-5 w-5 text-primary-500' }),
            h('h2', { class: 'text-lg font-semibold' }, 'Shortcuts Help'),
            h('span', { class: 'px-2 py-0.5 text-xs font-medium rounded bg-primary-100 dark:bg-primary-900 opacity-30 text-primary-700 dark:text-primary-300' },
              this.modKeyLabel + ' = ' + (this.isMac ? '⌘ Command' : 'Ctrl')),
          ]),
          h('button', { onClick: this.close, class: 'btn-icon text-text-muted hover:text-text', ariaLabel: 'Close' }, [
            h(X, { class: 'h-5 w-5' }),
          ]),
        ]),
        h('div', { class: 'flex-1 overflow-y-auto p-4 space-y-6' }, [
          this.shortcuts.map(group => h('div', { key: group.category, class: 'space-y-3' }, [
            h('h3', { class: 'text-sm font-medium text-text-muted uppercase tracking-wider' }, group.category),
            h('div', { class: 'grid grid-cols-1 sm:grid-cols-2 gap-2' }, group.items.map(item =>
              h('div', { key: item.key, class: 'flex items-center gap-3 p-3 rounded-lg bg-gray-50 dark:bg-gray-800 opacity-50' }, [
                h('kbd', {
                  class: 'font-mono text-xs px-2 py-1 rounded whitespace-nowrap bg-white dark:bg-gray-700 border border-canvas-border',
                }, this.getKeyDisplay(item.key)),
                h('span', { class: 'text-sm text-text' }, item.desc),
