              ]),
            ]),
          ])),
        ]),
      ]),
      h('footer', { class: 'flex items-center justify-between px-4 py-4 border-t border-canvas-border bg-white/80 dark:bg-gray-900/80 backdrop-blur-sm shrink-0' }, [
