import { h, ref, computed, nextTick, watch } from 'vue'
import { useSortable } from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import { Trash2, Copy, GripVertical, Palette } from 'lucide-vue-next'
import { useCanvasStore } from '@/stores'
import { useUIStore } from '@/stores/ui'
import { NOTE_COLORS, getNoteColor } from '@/types/note'

export default {
  setup() {
    const props = defineProps({
      note: { type: Object, required: true },
      presentationMode: { type: Boolean, required: true },
      blockId: { type: String, required: true },
    })

    const canvasStore = useCanvasStore()
    const uiStore = useUIStore()

    const isEditing = ref(false)
    const editTitle = ref('')
    const editContent = ref('')
    const showColorPicker = ref(false)
    const noteRef = ref(null)

    const noteColor = computed(() => getNoteColor(props.note.color))

    const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
      id: 'note-' + props.note.id,
      data: { blockId: props.blockId, noteId: props.note.id },
    })

    const style = computed(() => ({
      transform: CSS.Transform.toString(transform.value),
      transition: transition.value,
      opacity: isDragging.value ? 0.5 : 1,
      zIndex: isDragging.value ? 1000 : 1,
    })

    function handleClick(event) {
      if (event.detail === 2) {
        startEdit()
      }
    }

    function startEdit() {
      if (props.presentationMode) return
      isEditing.value = true
      editTitle.value = props.note.title
      editContent.value = props.note.content
      nextTick(() => {
        const titleEl = noteRef.value?.querySelector('[data-edit-title]')
        titleEl?.focus()
      })
    }

    function saveEdit() {
      if (!isEditing.value) return
      canvasStore.updateNote(props.note.id, {
        title: editTitle.value.trim(),
        content: editContent.value.trim(),
      })
      isEditing.value = false
    }

    function cancelEdit() {
      editTitle.value = props.note.title
      editContent.value = props.note.content
      isEditing.value = false
    }

    function handleTitleKeydown(event) {
      if (event.key === 'Enter') {
        event.preventDefault()
        const contentEl = noteRef.value?.querySelector('[data-edit-content]')
        contentEl?.focus()
      } else if (event.key === 'Escape') {
        cancelEdit()
      }
    }

    function handleContentKeydown(event) {
      if (event.key === 'Enter' && !event.shiftKey) {
        event.preventDefault()
        saveEdit()
      } else if (event.key === 'Escape') {
        cancelEdit()
      }
    }

    function handleBlur() {
      setTimeout(() => {
        if (isEditing.value && !showColorPicker.value) {
          saveEdit()
        }
      }, 100)
    }

    function deleteNote() {
      if (confirm('确定删除这张便利贴吗？')) {
        canvasStore.deleteNote(props.note.id)
      }
    }

    function duplicateNote() {
      canvasStore.duplicateNote(props.note.id)
    }

    function toggleColorPicker() {
      showColorPicker.value = !showColorPicker.value
    }

    function selectColor(colorId) {
      canvasStore.updateNote(props.note.id, { color: colorId })
      showColorPicker.value = false
    }

    function handlePointerDown(event) {
      if (event.target instanceof HTMLButtonElement || event.target instanceof HTMLInputElement || event.target instanceof HTMLTextAreaElement) return
    }

    watch(() => props.note.title, (val) => {
      if (!isEditing.value) editTitle.value = val
    })

    watch(() => props.note.content, (val) => {
      if (!isEditing.value) editContent.value = val
    })

    const ColorPickerMenu = {
      props: ['currentColor', 'onSelect', 'onClose'],
      emits: ['select', 'close'],
      setup(props, { emit }) {
        return () => h('div', {
          class: 'bg-white dark:bg-gray-800 rounded-lg shadow-xl border border-canvas-border p-2 flex gap-1',
          onClick: (e) => e.stopPropagation(),
        }, NOTE_COLORS.map(color => h('button', {
          key: color.id,
          class: `w-6 h-6 rounded-lg border-2 transition-all ${props.currentColor === color.id ? 'ring-2 ring-offset-2 ring-primary-500 scale-110' : 'hover:scale-110'}`,
          style: { backgroundColor: color.bg, borderColor: color.border },
          onClick: () => emit('select', color.id),
          'aria-label': color.id,
          'aria-pressed': props.currentColor === color.id,
        })))
      },
    }

    return {
      isEditing,
      editTitle,
      editContent,
      showColorPicker,
      noteRef,
      noteColor,
      attributes,
      listeners,
      setNodeRef,
      style,
      isDragging,
      handleClick,
      startEdit,
      saveEdit,
      cancelEdit,
      handleTitleKeydown,
      handleContentKeydown,
      handleBlur,
      deleteNote,
      duplicateNote,
      toggleColorPicker,
      selectColor,
      handlePointerDown,
      ColorPickerMenu,
    }
  },
  render() {
    return h('div', {
      ref: this.setNodeRef,
      vBind: this.attributes,
      class: 'sticky-note relative group bg-yellow-300 dark:bg-yellow-900 border border-yellow-400 dark:border-yellow-600 rounded-xl shadow-note hover:shadow-note-hover transition-all duration-200',
      style: [
        this.style,
        {
          backgroundColor: this.noteColor.bg,
          borderColor: this.noteColor.border,
        },
        this.presentationMode ? 'pointer-events-none' : '',
      ],
      class: { 'opacity-50': this.presentationMode },
      'data-color': this.note.color,
      'data-note-id': this.note.id,
      role: 'listitem',
      'aria-label': this.note.title || '无标题便利贴',
      onClick: this.handleClick,
      onPointerdown: this.handlePointerDown,
    }, [
      h('div', {
        class: 'absolute left-0 top-0 bottom-0 w-1 rounded-l-xl',
        style: { backgroundColor: this.noteColor.border },
      }),
      h('div', { class: 'p-3 min-h-[80px]' }, [
        h('div', { class: 'flex items-start justify-between gap-2 mb-1' }, [
          h('div', { vIf: this.isEditing, class: 'flex-1 min-w-0' }, [
            h('input', {
              ref: 'titleInput',
              vModel: this.editTitle,
              onKeydown: this.handleTitleKeydown,
              onBlur: this.handleBlur,
              'data-edit-title': true,
              class: 'w-full text-sm font-semibold bg-transparent text-text placeholder-text-muted focus:outline-none',
              placeholder: '标题',
              'aria-label': '便利贴标题',
            }),
          ]),
          h('div', {
            vElse: true,
            class: 'flex-1 min-w-0 font-semibold text-sm text-text',
            class: { 'line-clamp-1': !this.note.content },
          }, this.note.title || '无标题'),
          h('div', {
            vIf: !this.presentationMode && (this.showColorPicker || this.isDragging),
            class: 'flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity',
          }, [
            h('button', { onClick: this.toggleColorPicker, class: 'btn-icon p-1.5 text-text-muted hover:text-text', 'aria-label': '更改颜色' }, [
              h(Palette, { class: 'h-4 w-4' }),
            ]),
            h('button', { onClick: this.duplicateNote, class: 'btn-icon p-1.5 text-text-muted hover:text-text', 'aria-label': '复制' }, [
              h(Copy, { class: 'h-4 w-4' }),
            ]),
            h('button', { onClick: this.deleteNote, class: 'btn-icon p-1.5 text-text-muted hover:text-red-500', 'aria-label': '删除' }, [
              h(Trash2, { class: 'h-4 w-4' }),
            ]),
          ]),
        ]),
        h('div', { vIf: this.isEditing, class: 'min-h-[40px]' }, [
          h('textarea', {
            vModel: this.editContent,
            onKeydown: this.handleContentKeydown,
            onBlur: this.handleBlur,
            'data-edit-content': true,
            class: 'w-full text-sm text-text bg-transparent placeholder-text-muted focus:outline-none resize-none min-h-[40px]',
            placeholder: '内容',
            rows: 3,
            'aria-label': '便利贴内容',
          }),
        ]),
        h('div', {
          vElse: true,
          class: 'text-sm text-text/80 whitespace-pre-wrap break-words',
          class: { 'line-clamp-3': !this.isEditing && this.note.content.length > 200 },
        }, this.note.content),
      ]),
      h('div', { vIf: this.showColorPicker, class: 'absolute right-2 top-2 z-10' }, [
        h(ColorPickerMenu, {
          'current-color': this.props.note.color,
          onSelect: this.selectColor,
          onClose: () => this.showColorPicker = false,
        }),
      ]),
      h('div', { vIf: !this.presentationMode && !this.isEditing, class: 'absolute top-1 right-1 opacity-0 group-hover:opacity-100 transition-opacity draggable-handle' }, [
        h('button', { vBind: this.listeners, class: 'p-1 rounded hover:bg-black/10 dark:hover:bg-white/10 touch-pan-y', 'aria-label': '拖拽移动', onPointerdown: this.handlePointerDown }, [
          h(GripVertical, { class: 'h-5 w-5 text-text-muted' }),
        ]),
      ]),
    ])
  },
}
</script>

import { h, ref, computed, onMounted, onUnmounted, watch } from 'vue'
import { DndContext, closestCenter, KeyboardSensor, PointerSensor, TouchSensor, useSensor, useSensors } from '@dnd-kit/core'
import { arrayMove, SortableContext, sortableKeyboardCoordinates, verticalListSortingStrategy } from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import CanvasBlock from './CanvasBlock.js'
import { useCanvasStore } from '@/stores'

export default {
  components: {
    CanvasBlock,
  },
  setup() {
    const canvasStore = useCanvasStore()

    const gridRef = ref(null)
    const containerRef = ref(null)
    const isPanning = ref(false)
    const panStart = ref({ x: 0, y: 0 })
    const viewportStart = ref({ x: 0, y: 0 })

    const blocks = computed(() => canvasStore.currentTemplate?.blocks
      ? [...canvasStore.currentTemplate.blocks].sort((a, b) => a.order - b.order)
      : [])

    const notesByBlock = computed(() => {
      const map = new Map()
      canvasStore.currentCanvas?.notes.forEach(note => {
        if (!map.has(note.blockId)) map.set(note.blockId, [])
        map.get(note.blockId).push(note)
      })
      map.forEach(notes => notes.sort((a, b) => a.order - b.order))
      return map
    })

    const sensors = useSensors(
      useSensor(PointerSensor, {
        activationConstraint: { distance: 8, delay: 200 },
      }),
      useSensor(KeyboardSensor, {
        coordinateGetter: sortableKeyboardCoordinates,
      }),
      useSensor(TouchSensor, {
        activationConstraint: { delay: 200, tolerance: 8 },
      }),
    )

    function handleDragStart(event) {
      const { active } = event.detail
      const noteId = active.id
    }

    function handleDragEnd(event) {
      const { active, over } = event.detail
      if (!over) return

      const activeId = active.id
      const overId = over.id

      if (activeId.startsWith('note-') && overId.startsWith('note-')) {
        const activeNote = canvasStore.currentCanvas?.notes.find(n => n.id === activeId.replace('note-', ''))
        const overNote = canvasStore.currentCanvas?.notes.find(n => n.id === overId.replace('note-', ''))
        if (activeNote && overNote && activeNote.blockId === overNote.blockId) {
          canvasStore.reorderNotes(activeNote.blockId, activeNote.id, overNote.id)
        }
      } else if (activeId.startsWith('note-') && overId.startsWith('block-')) {
        const noteId = activeId.replace('note-', '')
        const blockId = overId.replace('block-', '')
        const blockNotes = canvasStore.currentCanvas?.notes.filter(n => n.blockId === blockId).sort((a, b) => a.order - b.order)
        const newOrder = blockNotes.length
        canvasStore.moveNote(noteId, blockId, newOrder)
      }
    }

    function handleDragOver(event) {
      const { active, over } = event.detail
      if (!over) return

      const activeId = active.id
      const overId = over.id

      if (activeId.startsWith('note-') && overId.startsWith('block-')) {
        const blockEl = document.getElementById(overId)
        blockEl?.classList.add('drag-over')
      }
    }

    function handleDragLeave(event) {
      const { over } = event.detail
      if (!over) return
      const overId = over.id
      if (overId.startsWith('block-')) {
        const blockEl = document.getElementById(overId)
        blockEl?.classList.remove('drag-over')
      }
    }

    function handleWheel(event) {
      if (event.ctrlKey || event.metaKey) {
        event.preventDefault()
        const container = containerRef.value
        if (!container) return

        const rect = container.getBoundingClientRect()
        const mouseX = event.clientX - rect.left
        const mouseY = event.clientY - rect.top

        const zoomFactor = event.deltaY > 0 ? 0.9 : 1.1
        const newScale = Math.min(Math.max(canvasStore.currentCanvas?.viewport.scale * zoomFactor || 1 * zoomFactor, 0.25), 3)

        const scaleRatio = newScale / (canvasStore.currentCanvas?.viewport.scale || 1)
        const newX = mouseX - (mouseX - (canvasStore.currentCanvas?.viewport.x || 0)) * scaleRatio
        const newY = mouseY - (mouseY - (canvasStore.currentCanvas?.viewport.y || 0)) * scaleRatio

        canvasStore.setViewport({ x: newX, y: newY, scale: newScale })
      }
    }

    function handlePointerDown(event) {
      if (event.button !== 0) return
      if (event.target.closest('.sticky-note, .block-header, button, input, textarea, [contenteditable]')) return

      isPanning.value = true
      panStart.value = { x: event.clientX, y: event.clientY }
      viewportStart.value = { x: canvasStore.currentCanvas?.viewport.x || 0, y: canvasStore.currentCanvas?.viewport.y || 0 }
      containerRef.value?.setPointerCapture(event.pointerId)
      event.target.style.cursor = 'grabbing'
    }

    function handlePointerMove(event) {
      if (!isPanning.value) return
      const dx = event.clientX - panStart.value.x
      const dy = event.clientY - panStart.value.y
      canvasStore.setViewport({
        x: viewportStart.value.x + dx,
        y: viewportStart.value.y + dy,
        scale: canvasStore.currentCanvas?.viewport.scale || 1,
      })
    }

    function handlePointerUp(event) {
      if (!isPanning.value) return
      isPanning.value = false
      containerRef.value?.releasePointerCapture(event.pointerId)
      event.target.style.cursor = ''
    }

    function handleDoubleClick() {
      canvasStore.setViewport({ x: 0, y: 0, scale: 1 })
    }

    function handleTouchStart(event) {
      if (event.touches.length === 2) {
        isPanning.value = true
        panStart.value = { x: event.touches[0].clientX, y: event.touches[0].clientY }
        viewportStart.value = { x: canvasStore.currentCanvas?.viewport.x || 0, y: canvasStore.currentCanvas?.viewport.y || 0 }
      }
    }

    function handleTouchMove(event) {
      if (!isPanning.value || event.touches.length !== 2) return
      event.preventDefault()
      const dx = event.touches[0].clientX - panStart.value.x
      const dy = event.touches[0].clientY - panStart.value.y
      canvasStore.setViewport({
        x: viewportStart.value.x + dx,
        y: viewportStart.value.y + dy,
        scale: canvasStore.currentCanvas?.viewport.scale || 1,
      })
    }

    function handleTouchEnd() {
      isPanning.value = false
    }

    return {
      gridRef,
      containerRef,
      isPanning,
      blocks: computed(() => canvasStore.currentTemplate?.blocks
        ? [...canvasStore.currentTemplate.blocks].sort((a, b) => a.order - b.order)
        : []),
      notesByBlock,
      sensors,
      handleDragStart,
      handleDragEnd,
      handleDragOver,
      handleDragLeave,
      handleWheel,
      handlePointerDown,
      handlePointerMove,
      handlePointerUp,
      handleDoubleClick,
      handleTouchStart,
      handleTouchMove,
      handleTouchEnd,
    }
  },
  render() {
    return h('div', {
      ref: 'containerRef',
      class: 'relative h-full w-full overflow-hidden bg-canvas-bg',
      class: { 'cursor-grab': !isPanning, 'cursor-grabbing': isPanning, 'touch-pan': !this.presentationMode },
      onWheelPassive: false,
    }, [
      h('div', {
        ref: 'gridRef',
        class: 'absolute top-0 left-0 transition-transform duration-75 ease-out',
        style: {
          transform: `translate(${canvasStore.currentCanvas?.viewport.x || 0}px, ${canvasStore.currentCanvas?.viewport.y || 0}px) scale(${canvasStore.currentCanvas?.viewport.scale || 1})`,
          transformOrigin: '0 0',
        },
        'data-export-ignore': this.presentationMode,
      }, [
        h('DndContext', {
          sensors: sensors,
          collisionDetection: closestCenter,
          onDragStart: handleDragStart,
          onDragEnd: handleDragEnd,
          onDragOver: handleDragOver,
          onDragLeave: handleDragLeave,
        }, [
          h('div', {
            class: 'grid gap-4 p-8',
            style: {
              gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
              width: 'fit-content',
              minHeight: '100%',
            },
            role: 'list',
            'aria-label': '画布区块',
          }, [
            this.blocks.map(block => h('CanvasBlock', {
              key: block.id,
              id: 'block-' + block.id,
              block,
              notes: this.notesByBlock.get(block.id) || [],
              presentationMode: this.presentationMode,
              onAddNote: (blockId) => this.canvasStore.addNote(blockId),
            })),
          ]),
        ]),
      ]),
    ])
  },
}
</script>

