import { h } from 'vue'
import { ChevronDown, Plus } from 'lucide-vue-next'

export default {
  props: {
    block: { type: Object, required: true },
    noteCount: { type: Number, default: 0 },
    collapsed: { type: Boolean, default: false },
    presentationMode: { type: Boolean, default: false },
  },
  emits: ['toggle-collapse', 'add-note'],
  setup(props) {
    return {}
  },
  computed: {
    headerStyle() {
      const c = this.block.color || '#e2e8f0'
      return { backgroundColor: c + '33' }
    },
    titleStyle() {
      return { color: this.block.color || 'inherit' }
    },
  },
  render() {
    const children = []

    if (!this.presentationMode) {
      children.push(h('button', {
        onClick: () => this.$emit('toggle-collapse'),
        class: 'p-1 rounded hover:bg-black/10 dark:hover:bg-white/10 transition-colors',
        'aria-label': this.collapsed ? '展开' : '折叠',
      }, [
        h(ChevronDown, {
          class: this.collapsed ? 'h-4 w-4 rotate-180' : 'h-4 w-4'
        }),
      ]))
    }

    children.push(h('h3', {
      class: 'font-semibold text-sm truncate flex-1',
      style: this.titleStyle,
    }, this.block.title))

    children.push(h('span', {
      class: 'px-2 py-0.5 text-xs font-medium rounded-full bg-primary-100 dark:bg-primary-900 text-primary-700 dark:text-primary-300'
    }, String(this.noteCount)))

    if (!this.presentationMode) {
      children.push(h('button', {
        onClick: () => this.$emit('add-note'),
        class: 'p-1.5 rounded hover:bg-black/10 dark:hover:bg-white/10 transition-colors text-text-muted hover:text-primary-600',
        'aria-label': '添加便利贴',
      }, [
        h(Plus, { class: 'h-4 w-4' }),
      ]))
    }

    return h('div', {
      class: 'flex items-center gap-2 px-3 py-2 border-b border-canvas-border',
      style: this.headerStyle,
    }, children)
  }
}

import { h, ref, computed, nextTick } from 'vue'
import { Trash2, Copy, GripVertical, Palette, Check } from 'lucide-vue-next'
import { useCanvasStore } from '@/stores'
import { NOTE_COLORS, getNoteColor } from '@/types/note'

export default {
  props: {
    note: { type: Object, required: true },
    presentationMode: { type: Boolean, default: false },
  },
  setup(props) {
    const canvasStore = useCanvasStore()

    const isEditing = ref(false)
    const editTitle = ref('')
    const editContent = ref('')
    const showColorPicker = ref(false)
    const noteRef = ref(null)
    const titleInputRef = ref(null)

    const noteColor = computed(function () {
      return getNoteColor(props.note.color)
    })

    function startEdit() {
      if (props.presentationMode) return
      isEditing.value = true
      editTitle.value = props.note.title
      editContent.value = props.note.content
      nextTick(function () {
        if (titleInputRef.value) {
          titleInputRef.value.focus()
        }
      })
    }

    function saveEdit() {
      canvasStore.updateNote(props.note.id, {
        title: editTitle.value.trim(),
        content: editContent.value.trim(),
      })
      isEditing.value = false
    }

    function cancelEdit() {
      isEditing.value = false
    }

    function handleTitleKeydown(event) {
      if (event.key === 'Enter') {
        event.preventDefault()
        saveEdit()
      } else if (event.key === 'Escape') {
        cancelEdit()
      }
    }

    function handleContentKeydown(event) {
      if (event.key === 'Enter' && !event.shiftKey) {
        event.preventDefault()
        saveEdit()
      } else if (event.key === 'Escape') {
        cancelEdit()
      }
    }

    function deleteNote() {
      canvasStore.deleteNote(props.note.id)
    }

    function duplicateNote() {
      canvasStore.duplicateNote(props.note.id)
    }

    function selectColor(colorId) {
      canvasStore.updateNote(props.note.id, { color: colorId })
      showColorPicker.value = false
    }

    function handleDragStart(event) {
      event.dataTransfer.effectAllowed = 'move'
      event.dataTransfer.setData('text/note-id', props.note.id)
      event.dataTransfer.setData('text/source-block', props.note.blockId || '')
      event.target.style.opacity = '0.4'
    }

    function handleDragEnd(event) {
      event.target.style.opacity = ''
    }

    return {
      isEditing,
      editTitle,
      editContent,
      showColorPicker,
      noteRef,
      titleInputRef,
      noteColor,
      startEdit,
      saveEdit,
      cancelEdit,
      handleTitleKeydown,
      handleContentKeydown,
      deleteNote,
      duplicateNote,
      selectColor,
      handleDragStart,
      handleDragEnd,
    }
  },
  render() {
    const self = this
    const color = this.noteColor

    // 颜色选择器
    let colorPickerNode = null
    if (this.showColorPicker) {
      const swatches = NOTE_COLORS.map(function (c) {
        const selected = c.id === self.note.color
        const swatchClass = 'w-6 h-6 rounded-lg border-2 transition-all hover:scale-110' +
          (selected ? ' ring-2 ring-primary-500 ring-offset-1' : '')
        return h('button', {
          key: c.id,
          class: swatchClass,
          style: { backgroundColor: c.bg, borderColor: c.border },
          onClick: function (e) {
            e.stopPropagation()
            self.selectColor(c.id)
          },
          'aria-label': c.id,
        })
      })
      colorPickerNode = h('div', {
        class: 'absolute right-2 top-8 z-20 bg-white dark:bg-gray-800 rounded-lg shadow-xl border border-canvas-border p-2 flex gap-1',
        onClick: function (e) { e.stopPropagation() }
      }, swatches)
    }

    // 操作按钮组（悬停显示）
    let actionsNode = null
    if (!this.presentationMode) {
      actionsNode = h('div', { class: 'flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity shrink-0' }, [
        h('button', {
          onClick: function () { self.showColorPicker = !self.showColorPicker },
          class: 'p-1 rounded hover:bg-black/10 dark:hover:bg-white/10 text-text-muted',
          'aria-label': '更改颜色',
        }, [h(Palette, { class: 'h-3.5 w-3.5' })]),
        h('button', {
          onClick: self.duplicateNote,
          class: 'p-1 rounded hover:bg-black/10 dark:hover:bg-white/10 text-text-muted',
          'aria-label': '复制',
        }, [h(Copy, { class: 'h-3.5 w-3.5' })]),
        h('button', {
          onClick: self.deleteNote,
          class: 'p-1 rounded hover:bg-black/10 dark:hover:bg-white/10 text-text-muted hover:text-red-500',
          'aria-label': '删除',
        }, [h(Trash2, { class: 'h-3.5 w-3.5' })]),
      ])
    }

    // 标题区
    let titleNode
    if (this.isEditing) {
      titleNode = h('input', {
        ref: 'titleInputRef',
        value: this.editTitle,
        onInput: function (e) { self.editTitle = e.target.value },
        onKeydown: self.handleTitleKeydown,
        onBlur: self.saveEdit,
        class: 'w-full text-sm font-semibold bg-transparent focus:outline-none text-text',
        placeholder: '标题...',
        'aria-label': '便利贴标题',
      })
    } else {
      titleNode = h('div', {
        class: 'flex-1 min-w-0 font-semibold text-sm text-text truncate cursor-text',
        onClick: self.startEdit,
      }, this.note.title || '无标题')
    }

    // 内容区
    let contentNode
    if (this.isEditing) {
      contentNode = h('textarea', {
        value: this.editContent,
        onInput: function (e) { self.editContent = e.target.value },
        onKeydown: self.handleContentKeydown,
        class: 'w-full text-sm bg-transparent focus:outline-none resize-none text-text mt-1',
        placeholder: '内容...',
        rows: 3,
        'aria-label': '便利贴内容',
      })
    } else {
      contentNode = h('div', {
        class: 'text-xs text-gray-700 dark:text-gray-300 whitespace-pre-wrap break-words mt-1 line-clamp-4 cursor-text',
        onClick: self.startEdit,
      }, this.note.content || '')
    }

    // 拖拽手柄
    let dragHandle = null
    if (!this.presentationMode) {
      dragHandle = h('div', {
        class: 'absolute top-1 left-1 opacity-0 group-hover:opacity-100 transition-opacity cursor-grab active:cursor-grabbing',
        draggable: true,
        onDragstart: self.handleDragStart,
        onDragend: self.handleDragEnd,
        'aria-label': '拖拽移动',
        title: '拖拽移动到其他区块',
      }, [
        h(GripVertical, { class: 'h-4 w-4 text-text-muted' }),
      ])
    }

    return h('div', {
      ref: 'noteRef',
      draggable: !this.presentationMode,
      onDragstart: this.handleDragStart,
      onDragend: this.handleDragEnd,
      class: 'sticky-note relative group rounded-lg shadow-note hover:shadow-note-hover transition-all duration-150 p-2.5 pl-3.5',
      style: {
        backgroundColor: color.bg,
        borderColor: color.border,
      },
      'data-note-id': this.note.id,
      role: 'listitem',
      'aria-label': this.note.title || '无标题便利贴',
    }, [
      // 左侧色条
      h('div', {
        class: 'absolute left-0 top-0 bottom-0 w-1 rounded-l-lg',
        style: { backgroundColor: color.border },
      }),
      dragHandle,
      h('div', { class: 'flex items-start gap-1' }, [
        titleNode,
        actionsNode,
      ]),
      contentNode,
      colorPickerNode,
    ])
  }
}

import { h, ref, computed } from 'vue'
import BlockHeader from './BlockHeader.js'
import StickyNote from './StickyNote.js'

export default {
  components: {
    BlockHeader,
    StickyNote,
  },
  props: {
    block: { type: Object, required: true },
    notes: { type: Array, default: function () { return [] } },
    presentationMode: { type: Boolean, default: false },
  },
  emits: ['add-note', 'note-moved'],
  setup(props) {
    const isCollapsed = ref(false)
    const isDragOver = ref(false)

    const sortedNotes = computed(function () {
      return props.notes.slice().sort(function (a, b) {
        return a.order - b.order
      })
    })

    return {
      isCollapsed,
      isDragOver,
      sortedNotes,
    }
  },
  methods: {
    handleDragOver(event) {
      if (this.presentationMode) return
      event.preventDefault()
      event.dataTransfer.dropEffect = 'move'
      this.isDragOver = true
    },
    handleDragLeave(event) {
      // 仅当离开整个区块时才移除高亮
      if (!event.currentTarget.contains(event.relatedTarget)) {
        this.isDragOver = false
      }
    },
    handleDrop(event) {
      this.isDragOver = false
      if (this.presentationMode) return
      event.preventDefault()
      const noteId = event.dataTransfer.getData('text/note-id')
      const sourceBlock = event.dataTransfer.getData('text/source-block')
      if (noteId && noteId !== '') {
        this.$emit('note-moved', {
          noteId: noteId,
          targetBlockId: this.block.id,
          sourceBlockId: sourceBlock,
        })
      }
    },
    toggleCollapse() {
      this.isCollapsed = !this.isCollapsed
    },
    addNote() {
      this.$emit('add-note', this.block.id)
    },
  },
  render() {
    const self = this

    const blockClass = 'flex flex-col min-h-[220px] rounded-xl border border-canvas-border shadow-block overflow-hidden transition-all duration-150 ' +
      (this.isDragOver ? 'ring-2 ring-primary-500 ring-offset-1' : '')

    const blockStyle = {
      borderTopColor: this.block.color || '#e2e8f0',
      borderTopWidth: '3px',
    }

    // 便利贴列表
    const noteNodes = this.sortedNotes.map(function (note) {
      return h('StickyNote', {
        key: note.id,
        note: note,
        presentationMode: self.presentationMode,
      })
    })

    // 空状态提示
    let emptyNode = null
    if (this.sortedNotes.length === 0 && !this.presentationMode) {
      emptyNode = h('div', {
        class: 'flex items-center justify-center border-2 border-dashed border-canvas-border rounded-lg text-text-muted text-xs p-4 m-2 cursor-pointer hover:border-primary-400 hover:text-primary-500 transition-colors',
        onClick: this.addNote,
        role: 'button',
        tabindex: 0,
      }, '双击或点击创建便利贴')
    }

    return h('div', {
      class: blockClass,
      style: blockStyle,
      role: 'listitem',
      'aria-label': this.block.title,
      onDragover: this.handleDragOver,
      onDragleave: this.handleDragLeave,
      onDrop: this.handleDrop,
    }, [
      h(BlockHeader, {
        block: this.block,
        noteCount: this.notes.length,
        collapsed: this.isCollapsed,
        presentationMode: this.presentationMode,
        onToggleCollapse: this.toggleCollapse,
        onAddNote: this.addNote,
      }),
      this.isCollapsed
        ? null
        : h('div', {
            class: 'flex-1 overflow-y-auto p-2 space-y-2 max-h-[400px] custom-scrollbar',
            role: 'list',
          }, noteNodes.concat(emptyNode ? [emptyNode] : [])),
    ])
  }
}

import { h, ref, computed, onMounted, onUnmounted } from 'vue'
import CanvasBlock from './CanvasBlock.js'
import { useCanvasStore } from '@/stores'

export default {
  components: {
    CanvasBlock,
  },
  setup() {
    const canvasStore = useCanvasStore()

    const containerRef = ref(null)
    const isPanning = ref(false)
    const panStart = ref({ x: 0, y: 0 })
    const viewportStart = ref({ x: 0, y: 0 })

    const blocks = computed(function () {
      const t = canvasStore.currentTemplate
      if (!t || !t.blocks) return []
      return t.blocks.slice().sort(function (a, b) {
        return a.order - b.order
      })
    })

    const notesByBlock = computed(function () {
      const map = new Map()
      const canvas = canvasStore.currentCanvas
      if (canvas) {
        canvas.notes.forEach(function (note) {
          if (!map.has(note.blockId)) map.set(note.blockId, [])
          map.get(note.blockId).push(note)
        })
        map.forEach(function (notes) {
          notes.sort(function (a, b) { return a.order - b.order })
        })
      }
      return map
    })

    function handleWheel(event) {
      if (event.ctrlKey || event.metaKey) {
        event.preventDefault()
        const canvas = canvasStore.currentCanvas
        if (!canvas) return

        const vp = canvas.viewport
        const zoomFactor = event.deltaY > 0 ? 0.9 : 1.1
        const newScale = Math.min(Math.max(vp.scale * zoomFactor, 0.25), 3)
        canvasStore.setViewport({ scale: newScale })
      }
    }

    function handlePointerDown(event) {
      if (event.button !== 0) return
      // 不拦截便利贴、按钮、输入框上的按下事件
      if (event.target.closest('.sticky-note, button, input, textarea, [contenteditable]')) return

      isPanning.value = true
      panStart.value = { x: event.clientX, y: event.clientY }
      const canvas = canvasStore.currentCanvas
      viewportStart.value = canvas
        ? { x: canvas.viewport.x, y: canvas.viewport.y }
        : { x: 0, y: 0 }
    }

    function handlePointerMove(event) {
      if (!isPanning.value) return
      const dx = event.clientX - panStart.value.x
      const dy = event.clientY - panStart.value.y
      canvasStore.setViewport({
        x: viewportStart.value.x + dx,
        y: viewportStart.value.y + dy,
      })
    }

    function handlePointerUp() {
      isPanning.value = false
    }

    function handleDoubleClick(event) {
      if (event.target.closest('.sticky-note, .canvas-block-inner')) return
      canvasStore.setViewport({ x: 0, y: 0, scale: 1 })
    }

    onMounted(function () {
      const el = containerRef.value
      if (el) {
        el.addEventListener('wheel', handleWheel, { passive: false })
      }
    })

    onUnmounted(function () {
      const el = containerRef.value
      if (el) {
        el.removeEventListener('wheel', handleWheel)
      }
    })

    function addNote(blockId) {
      canvasStore.addNote(blockId)
    }

    function handleNoteMoved(payload) {
      const canvas = canvasStore.currentCanvas
      if (!canvas) return
      const note = canvas.notes.find(function (n) { return n.id === payload.noteId })
      if (!note) return
      if (note.blockId === payload.targetBlockId) return

      const targetNotes = canvas.notes.filter(function (n) {
        return n.blockId === payload.targetBlockId
      })
      canvasStore.moveNote(payload.noteId, payload.targetBlockId, targetNotes.length)
    }

    return {
      containerRef,
      isPanning,
      blocks,
      notesByBlock,
      handlePointerDown,
      handlePointerMove,
      handlePointerUp,
      handleDoubleClick,
      addNote,
      handleNoteMoved,
    }
  },
  render() {
    const self = this
    const canvasStore = useCanvasStore()
    const canvas = canvasStore.currentCanvas
    const vp = canvas ? canvas.viewport : { x: 0, y: 0, scale: 1 }

    const containerClass = 'relative h-full w-full overflow-hidden bg-canvas-bg ' +
      (this.isPanning ? 'cursor-grabbing' : 'cursor-default')

    const blockNodes = this.blocks.map(function (block) {
      return h('CanvasBlock', {
        key: block.id,
        block: block,
        notes: self.notesByBlock.get(block.id) || [],
        presentationMode: false,
        onAddNote: self.addNote,
        onNoteMoved: self.handleNoteMoved,
      })
    })

    return h('div', {
      ref: 'containerRef',
      class: containerClass,
      onPointerdown: this.handlePointerDown,
      onPointermove: this.handlePointerMove,
      onPointerup: this.handlePointerUp,
      onPointerleave: this.handlePointerUp,
      onDblclick: this.handleDoubleClick,
    }, [
      h('div', {
        class: 'absolute top-0 left-0 p-6',
        style: {
          transform: 'translate(' + vp.x + 'px, ' + vp.y + 'px) scale(' + vp.scale + ')',
          transformOrigin: '0 0',
          width: '100%',
        },
      }, [
        h('div', {
          class: 'grid gap-4',
          style: {
            gridTemplateColumns: 'repeat(3, minmax(240px, 1fr))',
            maxWidth: '1200px',
            margin: '0 auto',
          },
          role: 'list',
          'aria-label': '画布区块',
        }, blockNodes),
      ]),
    ])
  }
}

