import { createServer } from 'vite'

async function verify() {
  const server = await createServer({
    root: process.cwd(),
    server: { port: 3999, strictPort: true },
    logLevel: 'silent',
  })

  await server.listen()
  const base = 'http://localhost:3999/canvas-pro/'

  // Test 1: index.html loads
  const res1 = await fetch(base)
  const html = await res1.text()
  console.log('1. index.html:', res1.status === 200 && html.includes('id="app"') ? 'PASS' : 'FAIL')

  // Test 2: main JS module transforms without error
  const res2 = await fetch(base + '@vite/client')
  console.log('2. vite client:', res2.status === 200 ? 'PASS' : 'FAIL')

  // Test 3: CanvasEditorView module transforms
  const res3 = await fetch(base + 'src/views/CanvasEditorView.js')
  const body3 = await res3.text()
  const ok3 = res3.status === 200 && !body3.includes('error')
