import { h, onMounted, ref, computed } from 'vue'
import { useRoute } from 'vue-router'
import { useCanvasStore } from '@/stores'
import { Edit, X, Maximize2 } from 'lucide-vue-next'

export default {
  setup() {
    const route = useRoute()
    const canvasStore = useCanvasStore()
    const isFullscreen = ref(false)

    const canvasData = ref<any>(null)

    function parseSharedData() {
      const hash = window.location.hash
      const match = hash.match(/#data=([^&]+)/)
      if (match) {
        try {
          const encoded = decodeURIComponent(match[1])
          const json = atob(encoded)
          return JSON.parse(json)
        } catch (e) {
          console.error('Failed to parse shared data:', e)
        }
      }
      return null
    }

    onMounted(() => {
      const data = parseSharedData()
      if (data) {
        canvasData.value = data
      }
    })

    function openEditor() {
      if (canvasData.value) {
        const canvas = canvasStore.importCanvas(JSON.stringify(canvasData.value))
        window.location.href = `/canvas-pro/#/canvas/${canvas.id}`
      }
    }

    function toggleFullscreen() {
      isFullscreen.value = !isFullscreen.value
    }

    const mainClass = computed(() => isFullscreen.value ? 'pt-16 h-full fixed inset-0 top-0' : 'pt-16 h-full')

    return {
      canvasData,
      isFullscreen,
      mainClass,
      openEditor,
      toggleFullscreen,
    }
  },
  render() {
    return h('div', { class: 'min-h-screen bg-canvas-bg' }, [
      h('header', { class: 'fixed top-0 left-0 right-0 z-40 bg-white dark:bg-gray-900 opacity-80 backdrop-blur-sm border-b border-canvas-border px-4 py-3', 'data-export-ignore': true }, [
        h('div', { class: 'max-w-7xl mx-auto flex items-center justify-between' }, [
          h('div', { class: 'flex items-center gap-3' }, [
            h('svg', { class: 'w-8 h-8 text-primary-600', viewBox: '0 0 32 32', fill: 'none' }, [
              h('rect', { width: '32', height: '32', rx: '6', fill: '#0ea5e9' }),
              h('path', { d: 'M8 10h16M8 16h12M8 22h8', stroke: 'white', strokeWidth: '2.5', strokeLinecap: 'round' }),
              h('rect', { x: '8', y: '10', width: '4', height: '4', rx: '1', fill: 'white', opacity: '0.3' }),
              h('rect', { x: '8', y: '16', width: '4', height: '4', rx: '1', fill: 'white', opacity: '0.3' }),
            ]),
            h('span', { class: 'text-lg font-semibold text-text' }, 'CanvasPro 预览'),
            h('span', { class: 'px-2 py-0.5 text-xs font-medium rounded bg-primary-100 dark:bg-primary-900 opacity-30 text-primary-700 dark:text-primary-300' }, '只读模式'),
          ]),
          h('div', { class: 'flex items-center gap-2' }, [
            h('button', { onClick: () => this.toggleFullscreen(), class: 'btn-icon', 'aria-label': this.isFullscreen ? '退出全屏' : '全屏' }, [
              h(Maximize2, { class: 'h-5 w-5' })
            ]),
            h('button', { onClick: () => this.openEditor(), class: 'btn-primary gap-2' }, [
              h(Edit, { class: 'w-4 h-4' }),
              '编辑副本'
            ]),
          ]),
        ]),
      ]),
      h('main', { class: this.mainClass }, [
        h('div', { class: 'max-w-7xl mx-auto h-full p-4' }, [
          h('div', { vIf: this.canvasData, class: 'h-full bg-canvas-bg rounded-xl border border-canvas-border overflow-hidden' }, [
            h('p', { class: 'text-center text-text-muted p-8' }, '预览模式 - 画布渲染开发中'),
            h('pre', { class: 'p-4 text-xs overflow-auto max-h-[60vh]' }, JSON.stringify(this.canvasData, null, 2)),
          ]),
          h('div', { vElse: true, class: 'h-full flex items-center justify-center' }, [
            h('div', { class: 'text-center' }, [
              h('p', { class: 'text-text-muted mb-4' }, '无效的分享链接'),
              h('p', { class: 'text-sm text-text-muted' }, '请检查链接是否完整，或从首页创建新画布'),
            ]),
          ]),
        ]),
      ]),
    ])
  },
}

